#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
d="$(mktemp -d)"
cd "$d" || exit 1
printf 'apple\napple\n' >file.txt
printf 'hello.txt\n' >note.txt
printf 'function f() { echo hi; }\n' >s.sh
ls | sort | grep '\.txt$' | wc -l
echo
cat file.txt | sort | uniq -c | sort -n -r
echo
find . -name '*.sh' | xargs grep -l function | tr -d '\\/'
echo
cat file.txt | tr a b | grep hello
echo
cat file.txt | sort | grep hello
cd /
rm -r -f "$d"
